begin;
with j as (select * from jsonb_to_recordset($law7d0037$[{"code_id":"GK_RF_2","article_number":"857","version_date":"1994-11-30","article_text":"1. Банк гарантирует тайну банковского счета и банковского вклада, операций по счету и сведений о клиенте.\n\n2. Сведения, составляющие банковскую тайну, могут быть предоставлены только самим клиентам или их представителям, а также представлены в бюро кредитных историй на основаниях и в порядке, которые предусмотрены законом. Государственным органам и их должностным лицам, а также иным лицам такие сведения могут быть предоставлены исключительно в случаях и порядке, которые предусмотрены законом.\n\n3. В случае разглашения банком сведений, составляющих банковскую тайну, клиент, права которого нарушены, вправе потребовать от банка возмещения причиненных убытков.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 857. Банковская тайна","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bc53324647f8705d7796ac04f09699c86f1ba9fbbcf36b51f692e7aa15bc61ba"},{"code_id":"GK_RF_2","article_number":"858","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено законом или договором, ограничение распоряжения денежными средствами, находящимися на счете, не допускается, за исключением наложения ареста на денежные средства, находящиеся на счете, или приостановления операций по счету, в том числе блокирования (замораживания) денежных средств в случаях, предусмотренных законом.\n\n2. Не допускается арест денежных средств на совместном счете по обязательствам одного из владельцев такого счета в размере, превышающем установленную договором или законом долю денежных средств, принадлежащих этому владельцу совместного счета.\n\nВ случае, когда договор совместного банковского счета заключен клиентами-супругами, между которыми не заключен брачный договор, арест денежных средств на совместном счете осуществляется в соответствии с правилами семейного законодательства об обращении взыскания на имущество супругов по общим обязательствам супругов и по обязательствам одного из них.\n\n3. Расторжение договора банковского счета не является основанием для снятия ареста, наложенного на денежные средства, находящиеся на счете, или отмены приостановления операций по счету. В этом случае указанные меры по ограничению распоряжения счетом распространяются на остаток денежных средств на счете (пункт 5 статьи 859).\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 858. Ограничение распоряжения счетом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e37f891bb96298fb7b7c36fff17ba4a9410ff1390083fd826ee81721208fa304"},{"code_id":"GK_RF_2","article_number":"859","version_date":"1994-11-30","article_text":"1. Договор банковского счета расторгается по заявлению клиента в любое время.\n\n2. При отсутствии в течение двух лет денежных средств на счете клиента - гражданина, не являющегося индивидуальным предпринимателем, и операций по этому счету банк вправе в одностороннем порядке отказаться от исполнения договора банковского счета, предупредив клиента об этом в письменной форме или иным предусмотренным договором способом, если договором банковского счета не предусмотрен отказ банка от этого права. Договор банковского счета считается расторгнутым по истечении двух месяцев со дня направления банком такого предупреждения, если на счет клиента в течение этого срока не поступили денежные средства.\n\nПри отсутствии в течение двух лет или в течение иного предусмотренного договором банковского счета срока операций по этому счету клиента - юридического лица или индивидуального предпринимателя банк вправе в одностороннем порядке отказаться от исполнения договора банковского счета, предупредив клиента об этом в письменной форме или иным способом, предусмотренным договором, если договором банковского\n\nсчета не предусмотрен отказ банка от этого права. При этом указанный срок в любом случае не может быть менее шести месяцев. Договор банковского счета считается расторгнутым по истечении двух месяцев со дня направления банком такого предупреждения.\n\n3. Банк вправе расторгнуть договор банковского счета в случаях, установленных законом, с обязательным письменным уведомлением об этом клиента. Договор банковского счета считается расторгнутым по истечении шестидесяти дней со дня направления банком клиенту уведомления о расторжении договора банковского счета.\n\nСо дня направления банком клиенту уведомления о расторжении договора банковского счета до дня, когда договор считается расторгнутым, банк не вправе осуществлять операции по банковскому счету клиента, за исключением операций по взиманию платы за услуги банка, начислению процентов, если такие условия содержатся в договоре банковского счета, по перечислению обязательных платежей в бюджет и операций, предусмотренных пунктами 5 и 6 настоящей статьи.\n\n4. По требованию банка договор банковского счета может быть расторгнут судом в следующих случаях:\n\nкогда сумма денежных средств, находящихся на счете клиента, окажется ниже минимального размера, предусмотренного банковскими правилами или договором, если такая сумма не будет восстановлена в течение месяца со дня предупреждения банка об этом;\n\nпри отсутствии операций по этому счету в течение года, если иное не предусмотрено договором.\n\n5. Остаток денежных средств на счете выдается клиенту либо по его указанию перечисляется на другой счет не позднее семи дней после получения соответствующего письменного заявления клиента, за исключением случаев, предусмотренных пунктом 3 статьи 858 настоящего Кодекса.\n\n6. В случае неявки клиента за получением остатка денежных средств на счете в течение шестидесяти дней со дня направления банком клиенту уведомления о расторжении договора банковского счета либо неполучения банком в течение указанного срока указания клиента о переводе суммы остатка денежных средств на другой счет банк обязан зачислить денежные средства на специальный счет в Банке России, порядок открытия и ведения которого, а также порядок зачисления и возврата денежных средств с которого устанавливается Банком России. При этом в случае расторжения договора банковского счета в иностранной валюте банк обязан осуществить продажу иностранной валюты, а в случае расторжения договора банковского счета в драгоценных металлах осуществить продажу драгоценного металла по курсу, установленному этим банком на день продажи иностранной валюты и (или) драгоценного металла, и перечислить денежные средства в валюте Российской Федерации на указанный счет в Банке России.\n\nПо требованию клиента банк осуществляет в порядке, установленном банковскими правилами, возврат денежных средств в валюте Российской Федерации в сумме, ранее перечисленной этим банком на специальный счет в Банке России.\n\n7. Расторжение договора банковского счета является основанием закрытия счета клиента.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 859. Расторжение договора банковского счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ad6862b55b7c65ba07e9f51019353fa40ae7c4f905d47f899cc9b26ea5dfd773"},{"code_id":"GK_RF_2","article_number":"859.1","version_date":"1994-11-30","article_text":"1. По договору банковского счета в драгоценных металлах банк обязуется принимать и зачислять поступающий на счет, открытый клиенту (владельцу счета), драгоценный металл, а также выполнять распоряжения клиента о его перечислении на счет, о выдаче со счета драгоценного металла того же наименования и той же массы либо о выдаче на условиях и в порядке, которые предусмотрены договором, денежных средств в сумме, эквивалентной стоимости этого металла.\n\nПорядок осуществления операций по банковскому счету в драгоценных металлах регулируется законом, а также установленными в соответствии с ним банковскими правилами.\n\n2. Договор банковского счета в драгоценных металлах должен содержать обязательное указание на наименование драгоценного металла, а также порядок расчета суммы денежных средств, подлежащих выдаче со счета, если возможность их выдачи предусмотрена договором.\n\n3. Если иное не установлено законом, установленными в соответствии с ним банковскими правилами или не вытекает из существа счета, к отношениям по договору банковского счета в драгоценных металлах, а также к отношениям, возникающим при проведении операций по счету, применяются правила о счетах, предусмотренные настоящим Кодексом, в том числе правила абзаца седьмого пункта 1 статьи 64 настоящего Кодекса.\n\nК отношениям по договору банковского счета в драгоценных металлах правила пункта 1 статьи 840 настоящего Кодекса об обеспечении возврата вкладов граждан путем осуществляемого в соответствии с законом страхования вкладов физических лиц не применяются, о чем клиент-гражданин должен быть уведомлен в письменной форме до заключения договора банковского счета в драгоценных металлах, а банк должен получить от гражданина подтверждение того, что такое уведомление было совершено.\n\n4. Совместный счет, номинальный счет, публичный депозитный счет и иные виды банковских счетов, предусмотренных законом, могут быть счетами в драгоценных металлах.\n\n(Дополнение статьей - Федеральный закон от 26.07.2017 № 212-ФЗ)","article_title":"Статья 859.1. Особенности договора банковского счета в драгоценных металлах","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d694a054b0841ed89279370ced2be681b2a4d9dd88cf4a58e1a6b7a5c91d270e"},{"code_id":"GK_RF_2","article_number":"860","version_date":"1994-11-30","article_text":"1. Общие положения о банковском счете применяются к отдельным видам банковских счетов (совместный счет, номинальный счет, публичный депозитный счет и иные виды банковских счетов, предусмотренных законом), если правилами об этих видах банковских счетов, предусмотренными главой 45 настоящего Кодекса и иными законами, не установлено иное.\n\n2. К договору залогового счета общие положения о банковском счете применяются в части, не урегулированной правилами о залоге прав по договору банковского счета (статьи 3589 - 35814).\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)\n\n(Дополнение абзацем - Федеральный закон от 26.07.2017 № 212-ФЗ)","article_title":"Статья 860. Применение общих положений о банковском счете к отдельным видам банковских счетов","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"238ed97f0ac20065dc6a2a10a5ed9040713506c155afb45ba5ffa8f886543557"},{"code_id":"GK_RF_2","article_number":"860.1","version_date":"1994-11-30","article_text":"1. Номинальный счет может открываться владельцу счета для совершения операций с денежными средствами, права на которые принадлежат другому лицу-бенефициару.\n\nПрава на денежные средства, поступающие на номинальный счет, в том числе в результате их внесения владельцем счета, принадлежат бенефициару.\n\nНоминальный счет может открываться для совершения операций с денежными средствами, права на которые принадлежат нескольким лицам-бенефициарам, за исключением случаев, установленных законом.\n\nВ случаях, предусмотренных законом, владелец счета может быть одновременно одним из нескольких бенефициаров, при этом в отношениях с банком такое лицо обязано всякий раз указывать, что действует в качестве владельца счета или в качестве бенефициара. (Дополнение абзацем - Федеральный закон от 30.12.2020 № 528-ФЗ)\n\n2. Существенным условием договора номинального счета является указание бенефициара либо порядка получения информации от владельца счета о бенефициаре или бенефициарах, а также основание их участия в отношениях по договору номинального счета.\n\n3. Законом или договором номинального счета с участием бенефициара на банк может быть возложена обязанность контролировать использование владельцем счета денежных средств в интересах бенефициара в пределах и в порядке, которые предусмотрены законом или договором.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 379-ФЗ) (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 860.1. Договор номинального счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4d9baee99953847067844e6911f0d63374fdc6e54671876dd7481bf61363f694"},{"code_id":"GK_RF_2","article_number":"860.10","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договором эскроу, закрытие счета эскроу осуществляется банком по истечении срока действия или прекращения по иным основаниям договора эскроу. Правила, установленные пунктами 1 и 2 статьи 859 настоящего Кодекса, не применяются к отношениям по счету эскроу.\n\n2. Если иное не предусмотрено соглашением депонента и бенефициара, при расторжении договора счета эскроу остаток денежных средств перечисляется или выдается депоненту либо при возникновении оснований для передачи денежных средств бенефициару перечисляется или выдается бенефициару.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 379-ФЗ) (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)\n\n(Дополнение параграфом - Федеральный закон от 26.07.2017 № 212-ФЗ)","article_title":"Статья 860.10. Закрытие счета эскроу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fb9f38b6470bc9ddcc40a4dd2078b903fd7136fcea73196b310843f6af51ab1b"},{"code_id":"GK_RF_2","article_number":"860.11","version_date":"1994-11-30","article_text":"1. По договору публичного депозитного счета, заключаемому для целей депонирования денежных средств в случаях, предусмотренных законом, банк обязуется принимать и зачислять в пользу бенефициара денежные средства, поступающие от должника или иного указанного в законе лица (депонента), на счет, открытый владельцу счета (нотариусу, службе судебных приставов, суду и иным органам или лицам, которые в соответствии с законом могут принимать денежные средства в депозит).\n\nПубличный депозитный счет может открываться в российских кредитных организациях, величина собственных средств (капитала) которых составляет не менее чем двадцать миллиардов рублей. В течение месяца со дня, когда владельцу публичного депозитного счета стало известно или должно было стать известно о том, что величина капитала кредитной организации составила менее указанной суммы, он обязан закрыть свой публичный счет в этой кредитной организации и перечислить все средства с него на другой свой публичный депозитный счет в другой российской кредитной организации, величина капитала которой составляет не менее указанной суммы.\n\n2. По договору публичного депозитного счета банк не вправе контролировать соответствие операций владельца публичного депозитного счета установленным законом правилам о депонировании, если иное не предусмотрено законом.\n\n3. Депонирование денежных средств на публичном депозитном счете влечет за собой возникновение требования к владельцу счета в отношении этих денежных средств у лица, в чью пользу они депонированы (бенефициар). Бенефициар не вправе требовать совершения операций с денежными средствами, поступившими на публичный депозитный счет в его пользу, непосредственно от банка.\n\n4. Бенефициар вправе потребовать от владельца счета перечисления (выдачи) бенефициару денежных средств с публичного депозитного счета по основаниям и в порядке, которые предусмотрены законом.","article_title":"Статья 860.11. Договор публичного депозитного счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e27c2c98b30098d5d2f77be35e2fa16cfddcde4a607dd1d8afe37a6d8e9ba800"},{"code_id":"GK_RF_2","article_number":"860.12","version_date":"1994-11-30","article_text":"1. По публичному депозитному счету на основании поручения (распоряжения) владельца счета могут совершаться операции по перечислению или выдаче депонированных денежных средств бенефициару и возврату этих денежных средств депоненту либо по его указанию другому лицу.\n\nСовершение иных операций по публичному депозитному счету и кредитование счета (статья 850) не допускаются, если иное не предусмотрено законом.\n\n2. Владелец публичного депозитного счета несет ответственность перед бенефициаром и депонентом за совершение операций по такому счету с нарушением правил о депонировании, установленных законом.\n\n3. Банк не несет ответственности перед бенефициаром и депонентом за совершение операций по публичному депозитному счету на основании поручения (распоряжения) владельца счета с нарушением установленных законом правил о депонировании, за исключением случая, когда банк не исполнил установленную в соответствии с законом обязанность по контролю за использованием денежных средств на счете.","article_title":"Статья 860.12. Операции по публичному депозитному счету, совершаемые банком","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a8713f66bf1bdc3b79e35fa2f9dab4a557d58c7de537956cf1f4dbb32564efcc"},{"code_id":"GK_RF_2","article_number":"860.13","version_date":"1994-11-30","article_text":"1. За пользование денежными средствами, находящимися на публичном депозитном счете, банк уплачивает проценты, сумма которых зачисляется на счет.\n\n2. Проценты, указанные в пункте 1 настоящей статьи, уплачиваются банком в размере, который обычно уплачивается банком по вкладам до востребования (статья 838), если иной размер процентов не предусмотрен договором публичного депозитного счета.\n\n3. Выплата депонированных для бенефициара денежных средств, а также их возврат депоненту осуществляется с учетом уплаченных или подлежащих уплате банком процентов за период с момента поступления депонированных денежных средств на публичный депозитный счет до их выплаты бенефициару или возврата депоненту за вычетом вознагражде\n\nния, причитающегося банку по договору публичного депозитного счета.","article_title":"Статья 860.13. Проценты за пользование банком денежными средствами, находящимися на публичном депозитном счете","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"06d91699923bf0ee0d2de1c81351e45f08949f1bae6a6ac699f2001b7851bda8"},{"code_id":"GK_RF_2","article_number":"860.14","version_date":"1994-11-30","article_text":"1. Арест, приостановление операций и списание денежных средств, находящихся на публичном депозитном счете, по обязательствам владельца счета перед его кредиторами и по обязательствам бенефициара или депонента не допускаются. Взыскание по обязательствам бенефициара или депонента может быть обращено на их право требования к владельцу счета.\n\n2. В случае неисполнения владельцем счета предусмотренной законом обязанности по выдаче или возврату депонированных денежных средств бенефициар или депонент вправе потребовать от владельца счета совершения соответствующих действий в судебном порядке.","article_title":"Статья 860.14. Распоряжение денежными средствами, находящимися на публичном депозитном счете","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1becb3e4bebffc529d503b83eedc144f7cbbb5b015989a533e0c0e9f4002aebb"},{"code_id":"GK_RF_2","article_number":"860.15","version_date":"1994-11-30","article_text":"1. В случае смерти нотариуса (иного уполномоченного на открытие публичного депозитного счета лица) или сложения им (прекращения) своих полномочий владелец публичного депозитного счета заменяется на другого нотариуса (иное лицо), которому в соответствии с законом, иными правовыми актами передаются дела нотариуса (иного лица), являвшегося владельцем счета.\n\n2. В случае упразднения или преобразования органа, который уполномочен на открытие публичного депозитного счета, владелец такого счета заменяется на другой орган, к компетенции которого в соответствии с законом, иными правовыми актами относится открытие публичного депозитного счета для депонирования денежных средств соответствующих депонентов.\n\n3. Договор публичного депозитного счета не может быть прекращен по основаниям, указанным в пунктах 2 и 4 статьи 859 настоящего Кодекса.","article_title":"Статья 860.15. Замена владельца публичного депозитного счета и прекращение договора","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2620b025ca1c59084b8dd7137d4623ecb28c1022babc54842f18e5716794dead"},{"code_id":"GK_RF_2","article_number":"860.2","version_date":"1994-11-30","article_text":"(Дополнение статьей - Федеральный закон от 21.12.2013 № 379-ФЗ) (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 860.2. Заключение договора номинального счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e1bb7373971a1cd726858adc9707e8a30028e7b9a060f1c799b0109da42a90dc"},{"code_id":"GK_RF_2","article_number":"860.3","version_date":"1994-11-30","article_text":"Законом или договором номинального счета может быть ограничен круг операций, которые могут совершаться по указанию владельца счета, в том числе путем определения:\n\n1) лиц, которым могут перечисляться или выдаваться денежные средства;\n\n2) лиц, с согласия которых совершаются операции по счету;\n\n3) документов, являющихся основанием совершения операций;\n\n4) иных обстоятельств.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 379-ФЗ) (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 860.3. Операции по номинальному счету","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"09dbe1149c1b61bf011c77d1f0854727bf0e6f2ac56e6a2066a1ccd99b2b10bd"},{"code_id":"GK_RF_2","article_number":"860.4","version_date":"1994-11-30","article_text":"1. Бенефициар по договору номинального счета вправе требовать от банка предоставления сведений, составляющих банковскую тайну, если такое право предоставлено бенефициару договором.\n\n2. Бенефициар по договору номинального счета с участием бенефициара вправе требовать от банка предоставления сведений, составляющих банковскую тайну.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 379-ФЗ) (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 860.4. Предоставление сведений, составляющих банковскую тайну, бенефициару по договору номинального счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5e1f9c9d1264206793774aef0eff8fb6d2cae30c410c822b99c0cc954c858407"},{"code_id":"GK_RF_2","article_number":"860.5","version_date":"1994-11-30","article_text":"1. Приостановление операций по номинальному счету, арест или списание денежных средств, находящихся на номинальном счете, по обязательствам владельца счета, за исключением обязательств, предусмотренных статьями 850 и 851 настоящего Кодекса, не допускается.\n\n2. Арест или списание денежных средств с номинального счета по обязательствам бенефициара допускается по решению суда. Списание денежных средств с номинального счета допускается также в случаях, предусмотренных законом или договором номинального счета.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 379-ФЗ) (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 860.5. Арест или списание денежных средств, находящихся на номинальном счете","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6bba4f9abafcbea268adf7c0c537661cfeb3a9104f0c29ffc95f1e21f27532c9"},{"code_id":"GK_RF_2","article_number":"860.6","version_date":"1994-11-30","article_text":"1. Договор номинального счета с участием бенефициара может быть изменен или расторгнут только с согласия бенефициара, если законом или договором номинального счета не предусмотрено иное.\n\n2. В случае поступления в банк заявления владельца счета о расторжении договора номинального счета банк обязан незамедлительно проинформировать об этом бенефициара.\n\n3. Если владельцем номинального счета является опекун или попечитель бенефициара, при прекращении исполнения обязанностей опекуна или попечителя такой владелец номинального счета заменяется на другого владельца, который в установленном законом порядке назначен опекуном или попечителем бенефициара. При прекращении опеки или попечительства в случаях, предусмотренных законом, в том числе при достижении бенефициаром совершеннолетия, договор номинального счета прекращается, остаток денежных средств по заявлению бенефициара выдается ему или перечисляется на другой его банковский счет.\n\n4. При расторжении договора номинального счета остаток денежных средств перечисляется на другой номинальный счет владельца или выдается бенефициару либо, если иное не предусмотрено законом или договором номинального счета либо не вытекает из существа отношений, по указанию бенефициара перечисляется на другой счет.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 379-ФЗ) (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)\n\n(Дополнение абзацем - Федеральный закон от 26.07.2017 № 212-ФЗ)","article_title":"Статья 860.6. Изменение и расторжение договора номинального счета, замена владельца номинального счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6e7a87b17ef8a1377c93c03bb7cf44bd59c747575f179904f97ab3d2f6fd0e88"},{"code_id":"GK_RF_2","article_number":"860.7","version_date":"1994-11-30","article_text":"1. По договору счета эскроу банк (эскроу-агент) открывает специальный счет эскроу для учета и блокирования денежных средств, полученных им от владельца счета (депонента) в целях их передачи другому лицу (бенефициару) при возникновении оснований, предусмотренных договором счета эскроу. Права на денежные средства, находящиеся на счете эскроу, принадлежат депоненту до даты возникновения оснований для передачи денежных средств бенефициару, а после указанной даты - бенефициару. Распоряжение денежными средствами, находящимися на счете эскроу, осуществляется в порядке, предусмотренном настоящим параграфом.\n\n2. Обязательства по договору счета эскроу могут содержаться наряду с договором счета эскроу в ином договоре, по которому эскроу-агентом является банк.\n\n3. Вознаграждение банка как эскроу-агента не может взиматься из денежных средств, находящихся на счете эскроу, если иное не предусмотрено договором.\n\n4. К отношениям сторон применяются общие положения о банковском счете и договоре эскроу (глава 471), если иное не предусмотрено настоящей статьей и статьями 8608 - 86010 настоящего Кодекса или не вытекает из существа отношений сторон.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 379-ФЗ) (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 860.7. Договор счета эскроу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"240677eb6196a8d6e111a2547577e2bd1c28301f580d8d56a86674ca5d999808"},{"code_id":"GK_RF_2","article_number":"860.8","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено договором, ни депонент, ни бенефициар не вправе распоряжаться денежными средствами, находящимися на счете эскроу, за исключением случаев, указанных в настоящей статье.\n\n2. Зачисление на счет эскроу иных денежных средств депонента, за исключением депонируемой суммы, указанной в договоре эскроу, не допускается.\n\n3. При возникновении оснований, предусмотренных договором счета эскроу, банк в установленный таким договором срок, а при его отсутствии - в течение десяти дней обязан выдать бенефициару депонированную сумму или перечислить ее на указанный им счет.\n\n4. Приостановление операций по счету эскроу, арест или списание денежных средств, находящихся на счете эскроу, по обязательствам депонента перед третьими лицами и по обязательствам бенефициара не допускается.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 379-ФЗ) (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 860.8. Ограничения по распоряжению денежными средствами и использованию счета эскроу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d121a514c0215a0c38d4820f014f7aae0b217031b5b1a1724e79e5d8ceec3eab"},{"code_id":"GK_RF_2","article_number":"860.9","version_date":"1994-11-30","article_text":"Право требовать от банка предоставления сведений, составляющих банковскую тайну, имеют как депонент, так и бенефициар.\n\n(Дополнение статьей - Федеральный закон от 21.12.2013 № 379-ФЗ) (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 860.9. Предоставление сведений, составляющих банковскую тайну, по договору счета эскроу","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6fda4f5f5a92837ba3d1e6167816d9df4ca67b18320560aa22698cb66d1e89e9"},{"code_id":"GK_RF_2","article_number":"861","version_date":"1994-11-30","article_text":"1. Расчеты с участием граждан, не связанные с осуществлением ими предпринимательской деятельности, могут производиться наличными деньгами (статья 140) без ограничения суммы или в безналичном порядке.","article_title":"Статья 861. Наличные и безналичные расчеты","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"aedb79c87a38d92ec134e3d084d188bcb96af825e4bcf41ac91b28518a8359b3"},{"code_id":"GK_RF_2","article_number":"862","version_date":"1994-11-30","article_text":"Расчеты цифровыми рублями могут осуществляться в формах, установленных законодательством Российской Федерации о национальной платежной системе. (Дополнение абзацем - Федеральный закон от 24.07.2023 № 339-ФЗ)\n\n(Пункт в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 862. Формы безналичных расчетов","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7fdcc1e5e918905577de702b8a8f1a0eaad0f99ddf71856e0693a7c61b695b99"},{"code_id":"GK_RF_2","article_number":"863","version_date":"1994-11-30","article_text":"1. При расчетах платежными поручениями банк плательщика обязуется по распоряжению плательщика перевести находящиеся на его банковском счете денежные средства на банковский счет получателя средств в этом или ином банке в сроки, предусмотренные законом, если более короткий срок не предусмотрен договором банковского счета либо не определен применяемыми в банковской практике обычаями.\n\n2. Порядок осуществления расчетов платежными поручениями регулируется законом, банковскими правилами, применяемыми в банковской практике обычаями или договором.\n\n3. Банк плательщика вправе привлекать другие банки (банки-посредники) для исполнения платежного поручения плательщика.\n\n4. Правила настоящего параграфа применяются к отношениям, связанным с осуществлением расчетов поручениями о переводе денежных средств без открытия банковского счета, с учетом особенностей, предусмотренных статьей 8661 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 863. Общие положения о расчетах платежными поручениями","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"01a95310c4a96b90c88281a9864a0db6cbb43a1173e0efd298e4d132db239365"},{"code_id":"GK_RF_2","article_number":"864","version_date":"1994-11-30","article_text":"1. Содержание (реквизиты) платежного поручения и его форма должны соответствовать требованиям, предусмотренным законом и банковскими правилами.\n\n2. При приеме к исполнению платежного поручения банк обязан удостовериться в праве плательщика распоряжаться денежными средствами, проверить соответствие платежного поручения установленным требованиям, достаточность денежных средств для исполнения платежного поручения, а также выполнить иные процедуры приема к исполнению распоряжений, предусмотренные законом, банковскими правилами и договором.\n\nПри отсутствии оснований для исполнения платежного поручения банк отказывает в приеме такого платежного поручения к исполнению с уведомлением об этом плательщика в срок не позднее дня, следующего за днем получения платежного поручения, если более короткий срок не установлен банковскими правилами и договором.\n\n3. Достаточность денежных средств, находящихся на банковском счете плательщика, для исполнения платежного поручения определяется в порядке, установленном законом, банковскими правилами и договором с учетом требований статьи 855 настоящего Кодекса.\n\nЕсли иное не предусмотрено законом, банковскими правилами и договором, при недостаточности денежных средств, находящихся на банковском счете плательщика, для исполнения платежного поручения банк не принимает платежное поручение к исполнению и уведомляет об этом плательщика в срок не позднее дня, следующего за днем поступления в банк платежного поручения.\n\n4. Прием платежного поручения к исполнению подтверждается банком в порядке, предусмотренном законом, банковскими правилами и договором.\n\n5. Платежное поручение может быть отозвано плательщиком до наступления момента безотзывности перевода денежных средств, определяемого в соответствии с законом.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 864. Прием к исполнению банком платежного поручения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"979f66ff3162b1cfa9010a897525eb6b65fcf1001d30840d75a15aa1b9a6e830"},{"code_id":"GK_RF_2","article_number":"865","version_date":"1994-11-30","article_text":"1. Банк плательщика, принявший к исполнению платежное поручение, в соответствии с распоряжением плательщика обязан его исполнить одним из следующих способов:\n\n1) зачисление денежных средств на банковский счет получателя средств, открытый в этом же банке;\n\n2) зачисление денежных средств на банковский счет банка получателя средств, открытый в банке плательщика, либо передача платежного поручения банку получателя средств для списания денежных средств с банковского счета банка плательщика, открытого в банке получателя средств;\n\n3) передача платежного поручения банку-посреднику в целях зачисления денежных средств на банковский счет банка получателя средств;\n\n4) иные способы, предусмотренные банковскими правилами и договором.\n\n2. Банк обязан информировать плательщика об исполнении его платежного поручения в срок не позднее дня, следующего за днем исполнения платежного поручения, если более короткий срок не установлен банковскими правилами и договором. Порядок такого информирования определяется банковскими правилами и договором.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 865. Исполнение банком платежного поручения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5bc8062628d8e203226d02c955dcf88a63094fe2ba57351d3b6db2e36ae37803"},{"code_id":"GK_RF_2","article_number":"866","version_date":"1994-11-30","article_text":"1. В случае неисполнения или ненадлежащего исполнения платежного поручения банк несет ответственность перед плательщиком в соответствии с главой 25 настоящего Кодекса с учетом положений, предусмотренных настоящей статьей.\n\n2. В случаях, если неисполнение или ненадлежащее исполнение платежного поручения имело место в связи с нарушением банком-посредником или банком получателя средств правил перевода денежных средств или договора между банками, ответственность перед плательщиком может быть возложена судом на банк-посредник или банк получателя средств, которые в этом случае отвечают перед плательщиком солидарно. Банк плательщика может быть привлечен к солидарной ответственности в указанных случаях, если он осуществил выбор банка-посредника.\n\n3. Если нарушение правил перевода денежных средств или условий договора повлекло несвоевременный перевод денежных средств, банки обязаны уплатить проценты в порядке и в размере, которые предусмотрены статьей 395 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 866. Ответственность банка за неисполнение или ненадлежащее исполнение платежного поручения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"aca9fdad2a392bec9c45891d6e0643b3d3da5b099d581dcadd9a80abdec76d6a"},{"code_id":"GK_RF_2","article_number":"866.1","version_date":"1994-11-30","article_text":"1. При переводе денежных средств без открытия банковского счета банк плательщика обязуется перевести без открытия банковского счета плательщику-гражданину на основании его распоряжения предоставленные им наличные денежные средства получателю средств в этом или ином банке.\n\n2. Достаточность денежных средств для исполнения распоряжения о переводе без открытия банковского счета определяется исходя из суммы предоставленных банку плательщиком наличных денежных средств.\n\n(Дополнение статьей - Федеральный закон от 26.07.2017 № 212-ФЗ)","article_title":"Статья 866.1. Особенности расчетов без открытия банковского счета","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"87289d876ffed07dadc19128197f562240bea4954854698f7b034b9797493c86"},{"code_id":"GK_RF_2","article_number":"867","version_date":"1994-11-30","article_text":"1. При расчетах по аккредитиву банк-эмитент, действующий по поручению плательщика, обязуется перед получателем средств произвести платежи или акцептовать и оплатить переводной вексель, выставленный получателем средств, либо совершить иные действия по исполнению аккредитива по представлении получателем средств предусмотренных аккредитивом документов и в соответствии с условиями аккредитива.\n\n2. Банк-эмитент может уполномочить другой банк (исполняющий банк) произвести платежи или акцептовать и оплатить переводной вексель, выставленный получателем средств, либо совершить иные действия по исполнению аккредитива по представлении получателем средств предусмотренных аккредитивом документов и в соответствии с условиями аккредитива.\n\nИсполняющий банк вправе принять поручение банка-эмитента или отказаться от такого поручения, направив банку-эмитенту соответствующее уведомление. Частичный отказ исполняющего банка от исполнения поручения не допускается. Исполняющий банк считается принявшим поручение банка-эмитента, если он прямо выразил на это согласие, в том числе путем совершения действий в соответствии с условиями аккредитива. Согласие исполняющего банка на исполнение аккредитива не препятствует его исполнению банком-эмитентом.\n\n3. В случае открытия покрытого (депонированного) аккредитива банк-эмитент обязан перечислить сумму аккредитива (покрытие) за счет плательщика либо предоставленного ему кредита в распоряжение исполняющего банка на весь срок действия обязательства банка-эмитента.\n\nВ случае открытия непокрытого (гарантированного) аккредитива банк-эмитент может предоставить исполняющему банку, принявшему поручение банка-эмитента, при осуществлении действий по исполнению аккредитива право списывать средства со счета банка-эмитента, открытого в исполняющем банке, в пределах суммы аккредитива либо может указать в аккредитиве иной способ возмещения исполняющему банку сумм, выплаченных им по аккредитиву. При исполнении непокрытого аккредитива исполняющий банк вправе не осуществлять исполнение аккредитива до поступления денежных средств от банка-эмитента, за исключением случая подтверждения аккредитива исполняющим банком.\n\n4. Аккредитив считается открытым с указанной в нем даты открытия аккредитива, если иное не предусмотрено законом, банковскими правилами и договором.\n\nБанк, дающий инструкции другому банку по совершению действий по аккредитиву, обязан оплачивать или компенсировать любые комиссии или затраты такого банка, связанные с выполнением им полученных инструкций. Банк-эмитент, пользующийся услугами другого банка для выполнения инструкций плательщика, делает это за счет плательщика и на его риск. Плательщик обязан возместить банку-эмитенту все расходы, понесенные им в связи с выполнением его инструкций по аккредитиву.\n\n5. Расчеты по аккредитиву регулируются настоящим Кодексом, банковскими правилами, условиями аккредитива, а в части, ими не урегулированной, обычаями, применяемыми в банковской практике.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 867. Общие положения о расчетах по аккредитиву","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"56c07d870cd14e042ff814fb5ba730f14a91ae9dad1505a224ef477a60ac98fe"},{"code_id":"GK_RF_2","article_number":"868","version_date":"1994-11-30","article_text":"1. Отзывный аккредитив может быть изменен или отменен по поручению плательщика банком-эмитентом в любой момент без предварительного уведомления получателя средств.\n\n2. Исполняющий банк осуществляет платеж или иные операции по отзывному аккредитиву, если к моменту их совершения им не получено уведомление банка-эмитента об изменении или отмене аккредитива.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 868. Отзывный аккредитив","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5bc7a564feff624c0fe04006a181795fd3f99b427c3da2f492755c3931d13673"},{"code_id":"GK_RF_2","article_number":"869","version_date":"1994-11-30","article_text":"1. Безотзывный аккредитив не может быть отменен банком-эмитентом без согласия получателя средств и банка, подтвердившего аккредитив. Безотзывный аккредитив не может быть изменен банком-эмитентом без согласия получателя средств.\n\n2. Для изменения или отмены безотзывного аккредитива по поручению плательщика банк-эмитент должен направить получателю средств соответствующее уведомление. Аккредитив считается отмененным или измененным с момента получения банком-эмитентом согласия получателя средств.\n\n3. Если аккредитив был подтвержден другим банком (статья 870), такой банк вправе не согласиться с изменением безотзывного аккредитива, при этом он обязан незамедлительно сообщить об этом банку-эмитенту и получателю средств.\n\n4. Аккредитив является безотзывным, если в его тексте не предусмотрено иное.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 869. Безотзывный аккредитив","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8a7d62972b830443ed4b9668c0420c6f2f1b4117ff1ec1b57082fad17ab76269"},{"code_id":"GK_RF_2","article_number":"870","version_date":"1994-11-30","article_text":"1. По просьбе банка-эмитента безотзывный аккредитив может быть подтвержден другим банком (подтверждающий банк). После подтверждения аккредитива подтверждающий банк становится обязанным перед бенефициаром по аккредитиву в пределах подтвержденной им суммы солидарно с банком-эмитентом.\n\nОбязательство подтверждающего банка возникает с момента направления получателю средств либо банку получателя уведомления о подтверждении аккредитива, если уведомлением не предусмотрено иное.\n\n2. В случае изменения аккредитива подтверждающий банк становится обязанным на измененных условиях аккредитива, если он дал на это согласие. В остальных случаях подтверждающий банк считается обязанным на прежних условиях аккредитива.\n\nОбязательство подтверждающего банка по аккредитиву с учетом внесенных в него изменений возникает с момента направления получателю либо банку получателя уведомления об этом, если уведомлением не предусмотрено иное.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 870. Подтвержденный аккредитив","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0f3aedccf9a09ff907b2886c6a4324b568f5a6f3c21ada49357bf50a34ad8724"},{"code_id":"GK_RF_2","article_number":"870.1","version_date":"1994-11-30","article_text":"1. Исполнение аккредитива может осуществляться лицу, указанному получателем средств, если возможность такого исполнения предусмотрена условиями аккредитива и исполняющий банк выразил свое согласие на такое исполнение (далее - переводной (трансферабельный) аккредитив). При этом получатель средств вправе определить документы, которые должны быть представлены указанным им лицом для исполнения переводного (трансферабельного) аккредитива. Эти документы могут быть не предусмотрены условиями переводного (трансферабельного) аккредитива.\n\nК отношениям, возникающим при исполнении аккредитива в соответствии с настоящей статьей, положения параграфа 1 главы 24 настоящего Кодекса не применяются.\n\n2. Получатель средств вправе указать лицо, которому должно производиться исполнение переводного (трансферабельного) аккредитива (далее - второй получатель средств) до момента представления им документов, соответствующих условиям открытого в его пользу аккредитива, в заявлении, представляемом в исполняющий банк. Получатель средств вправе указать несколько вторых получателей средств.\n\n3. Второй получатель средств не вправе указывать иное лицо, которому должен быть исполнен переводной (трансферабельный) аккредитив, за исключением получателя средств.\n\n4. Порядок и условия исполнения переводного (трансферабельного) аккредитива определяются законом, банковскими правилами и условиями аккредитива.\n\n(Дополнение статьей - Федеральный закон от 26.07.2017 № 212-ФЗ)","article_title":"Статья 870.1. Переводной (трансферабельный) аккредитив","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b847c2d51e6d19f4773e26d0d8f13d0b6c7f1db8a2fa64016ab28387eb45287f"},{"code_id":"GK_RF_2","article_number":"871","version_date":"1994-11-30","article_text":"1. Исполнение аккредитива может быть произведено путем:\n\n1) платежа получателю средств, осуществляемого банком по предъявлении ему документов, соответствующих условиям аккредитива, непосредственно либо в срок или сроки, предусмотренные условиями аккредитива;\n\n2) акцепта переводного векселя с его оплатой по наступлении срока платежа;\n\n3) иными способами, указанными в аккредитиве.\n\n2. Для исполнения аккредитива получатель средств представляет документы, в том числе в электронной форме, предусмотренные условиями аккредитива, в исполняющий банк или банк-эмитент. Исполняющий банк или банк-эмитент, получившие указанные документы, проверяют их в срок, не превышающий пяти рабочих дней со дня их получения, и принимают решение о выплате или об отказе от выплаты.\n\n3. Исполнение аккредитива производится при условии, что представленные документы по внешним признакам соответствуют условиям аккредитива, и не может быть обусловлено обязательством или обязательствами плательщика либо получателя средств, даже если в аккредитиве содержится ссылка на такое обязательство или такие обязательства.\n\n4. Проверка представленных документов осуществляется банком по внешним признакам.\n\nЕсли представленные документы по внешним признакам не соответствуют условиям аккредитива, банк вправе не исполнять аккредитив. Документы, которые по внешним признакам не соответствуют друг другу, должны рассматриваться как не соответствующие условиям аккредитива.\n\n5. В случае открытия покрытого (депонированного) аккредитива исполняющий банк исполняет аккредитив за счет покрытия по такому аккредитиву.\n\nЕсли исполняющий банк исполнил непокрытый (гарантированный) аккредитив, банк-эмитент или подтверждающий банк обязан возместить ему понесенные расходы. Указанные расходы возмещаются подтверждающему банку банком-эмитентом, а банку-эмитенту плательщиком. Плательщик обязан выплатить банку-эмитенту суммы, уплаченные по аккредитиву, независимо от исполнения банком-эмитентом своих обязательств перед исполняющим банком и подтверждающим банком, в том числе в случае, если исполняющим банком или подтверждающим банком банку-эмитенту предоставлена отсрочка.\n\n6. Документы, принятые исполняющим банком, представляются им в банк-эмитент или подтверждающий банк (при его наличии). Документы, принятые подтверждающим банком, представляются им в банк-эмитент. Банк, получивший представленные документы, проверяет их в срок, не превышающий пяти рабочих дней со дня их получения, и возмещает расходы по исполнению непокрыто\n\nго (гарантированного) аккредитива или отказывает в возмещении таких расходов. В случае установления банком, получившим представленные документы, несоответствия представленных документов условиям покрытого (депонированного) аккредитива банк, получивший представленные документы, вправе потребовать от исполняющего банка сумму денежных средств, перечисленных по исполненному аккредитиву.\n\n7. Получатель средств не вправе уступить полностью или частично право (требование) по аккредитиву, если иное не предусмотрено условиями аккредитива.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 871. Исполнение аккредитива","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"892f0b1109fa2bf75e299b6a4c1174b60b1a84a4f2908bce01712a3db8a2fd7b"},{"code_id":"GK_RF_2","article_number":"872","version_date":"1994-11-30","article_text":"1. Банк-эмитент и подтверждающий банк, принявшие на себя обязательства по аккредитиву, несут перед получателем средств солидарную ответственность за неисполнение или ненадлежащее исполнение аккредитива при условии представления документов, соответствующих условиям аккредитива, и выполнения иных условий аккредитива.\n\nПри необоснованном отказе исполняющего банка в выплате денежных средств по аккредитиву ответственность перед получателем средств может быть возложена судом на исполняющий банк.\n\n2. Исполняющий банк, который принял поручение по исполнению аккредитива, несет ответственность за неисполнение или ненадлежащее исполнение аккредитива перед банком-эмитентом.\n\n3. Банк-эмитент, принявший к исполнению поручение плательщика об открытии и исполнении аккредитива, несет перед ним ответственность за неисполнение или ненадлежащее исполнение этого поручения. Подтверждающий банк, принявший к исполнению поручение банка-эмитента о подтверждении и исполнении аккредитива, несет ответственность за неисполнение или ненадлежащее исполнение этого поручения перед банком-эмитентом.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 872. Ответственность банков","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7e9db48de42e5bdb44a88b36e814a5d3c06b55e477e5b8e21b497f593d88a8dc"},{"code_id":"GK_RF_2","article_number":"873","version_date":"1994-11-30","article_text":"1. Закрытие аккредитива в исполняющем банке производится:\n\n1) по истечении срока действия аккредитива, за исключением случая, когда документы по аккредитиву были представлены в пределах срока действия аккредитива;\n\n2) при полном исполнении аккредитива;\n\n3) по заявлению получателя средств об отказе от использования аккредитива до истечения срока его действия;\n\n4) по заявлению плательщика об отмене или отзыве аккредитива.\n\n2. О закрытии аккредитива исполняющий банк должен поставить в известность банк-эмитент.\n\n3. Неиспользованная сумма аккредитива подлежит возврату банку-эмитенту одновременно с закрытием аккредитива. Банк-эмитент обязан зачислить возвращенную денежную сумму на банковский счет плательщика, с которого депонировались эти средства.\n\n(Статья в редакции Федерального закона от 26.07.2017 № 212-ФЗ)","article_title":"Статья 873. Закрытие аккредитива","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e3c7cd67f1375c84a5dbb3434a5faf1da054b089fc2187cc1193594b3918ed6e"},{"code_id":"GK_RF_2","article_number":"874","version_date":"1994-11-30","article_text":"1. При расчетах по инкассо банк (банк-эмитент) обязуется по поручению клиента осуществить за счет клиента действия по получению от плательщика платежа и (или) акцепта платежа.\n\n2. Банк-эмитент, получивший поручение клиента, вправе привлекать для его выполнения иной банк (исполняющий банк).\n\nПорядок осуществления расчетов по инкассо регулируется законом, банковскими правилами и применяемыми в банковской практике обычаями. (В редакции Федерального закона от 26.07.2017 № 212-ФЗ)\n\n3. В случае неисполнения или ненадлежащего исполнения поручения клиента банк-эмитент несет перед ним ответственность по основаниям и в размере, которые предусмотрены главой 25 настоящего Кодекса.\n\nЕсли неисполнение или ненадлежащее исполнение поручения клиента имело место в связи с нарушением правил совершения расчетных операций исполняющим банком, ответственность перед клиентом может быть возложена на этот банк.","article_title":"Статья 874. Общие положения о расчетах по инкассо","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"03649542b153d96f47b3e7913ab4313e9520c8ff7fb5b116a8e57cd86fd9f2db"},{"code_id":"GK_RF_2","article_number":"875","version_date":"1994-11-30","article_text":"1. При отсутствии какого-либо документа или несоответствии документов по внешним признакам инкассовому поручению исполняющий банк обязан немедленно известить об этом лицо, от которого было получено инкассовое поручение. В случае неустранения указанных недостатков банк вправе возвратить документы без исполнения.\n\n2. Документы представляются плательщику в той форме, в которой они получены, за исключением отметок и надписей банков, необходимых для оформления инкассовой операции.\n\n3. Если документы подлежат оплате по предъявлении, исполняющий банк должен сделать представление к платежу немедленно по получении инкассового поручения.\n\nЕсли документы подлежат оплате в иной срок, исполняющий банк должен для получения акцепта плательщика представить документы к акцепту немедленно по получении инкассового поручения, а требование платежа должно быть сделано не позднее дня наступления указанного в документе срока платежа.\n\n4. Частичные платежи могут быть приняты в случаях, когда это установлено банковскими правилами, либо при наличии специального разрешения в инкассовом поручении.","article_title":"Статья 875. Исполнение инкассового поручения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"baf363194dbef82c93430fc6c74575195062196f0835bbbb8bd5f258634e2e48"},{"code_id":"GK_RF_2","article_number":"876","version_date":"1994-11-30","article_text":"1. Если платеж и (или) акцепт не были получены, исполняющий банк обязан немедленно известить банк-эмитент о причинах неплатежа или отказа от акцепта.\n\nБанк-эмитент обязан немедленно информировать об этом клиента, запросив у него указания относительно дальнейших действий.\n\n2. При неполучении указаний о дальнейших действиях в срок, установленный банковскими правилами, а при его отсутствии в разумный срок исполняющий банк вправе возвратить документы банку-эмитенту.","article_title":"Статья 876. Извещение о проведенных операциях","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b2fa2bec02b99cf72451bc3905eea625676aae96d39c3a309dea46076ceded7e"},{"code_id":"GK_RF_2","article_number":"877","version_date":"1994-11-30","article_text":"1. Чеком признается ценная бумага, содержащая ничем не обусловленное распоряжение чекодателя банку произвести платеж указанной в нем суммы чекодержателю.\n\n2. В качестве плательщика по чеку может быть указан только банк, где чекодатель имеет средства, которыми он вправе распоряжаться путем выставления чеков.\n\n3. Отзыв чека до истечения срока для его предъявления не допускается.\n\n4. Выдача чека не погашает денежного обязательства, во исполнение которого он выдан.\n\n5. Порядок и условия использования чеков в платежном обороте регулируются настоящим Кодексом, а в части, им не урегулированной, другими законами и устанавливаемыми в соответствии с ними банковскими правилами.","article_title":"Статья 877. Общие положения о расчетах чеками","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"96805c1302337900a7a2fb881e17cf7175b2f4ef713b24a500dbb1899718c32f"},{"code_id":"GK_RF_2","article_number":"878","version_date":"1994-11-30","article_text":"1. Чек должен содержать:\n\n1) наименование \"чек\", включенное в текст документа;\n\n2) поручение плательщику выплатить определенную денежную сумму;\n\n3) наименование плательщика и указание счета, с которого должен быть произведен платеж;\n\n4) указание валюты платежа;\n\n5) указание даты и места составления чека;\n\n6) подпись лица, выписавшего чек, - чекодателя.\n\nОтсутствие в документе какого-либо из указанных реквизитов лишает его силы чека.\n\nЧек, не содержащий указание места его составления, рассматривается как подписанный в месте нахождения чекодателя.\n\nУказание о процентах считается ненаписанным.\n\n2. Форма чека и порядок его заполнения определяются законом и установленными в соответствии с ним банковскими правилами.","article_title":"Статья 878. Реквизиты чека","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b5ef5d3373b20ccb56dfed4edbd172bc76e8bf752662f75502db5fc7692f72a9"},{"code_id":"GK_RF_2","article_number":"879","version_date":"1994-11-30","article_text":"1. Чек оплачивается за счет средств чекодателя.\n\nВ случае депонирования средств порядок и условия депонирования средств для покрытия чека устанавливаются банковскими правилами.\n\n2. Чек подлежит оплате плательщиком при условии предъявления его к оплате в срок, установленный законом.\n\n3. Плательщик по чеку обязан удостовериться всеми доступными ему способами в подлинности чека, а также в том, что предъявитель чека является уполномоченным по нему лицом.\n\nПри оплате индоссированного чека плательщик обязан проверить правильность индоссаментов, но не подписи индоссантов.\n\n4. Убытки, возникшие вследствие оплаты плательщиком подложного, похищенного или утраченного чека, возлагаются на плательщика или чекодателя в зависимости от того, по чьей вине они были причинены.\n\n5. Лицо, оплатившее чек, вправе потребовать передачи ему чека с распиской в получении платежа.","article_title":"Статья 879. Оплата чека","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9a4e0747f93d4e8c31972c91a5f90da7a1b211bde3fdec600fd837df206a639c"},{"code_id":"GK_RF_2","article_number":"880","version_date":"1994-11-30","article_text":"1. Передача прав по чеку производится в порядке, установленном статьей 146 настоящего Кодекса, с соблюдением правил, предусмотренных настоящей статьей.\n\n2. Именной чек не подлежит передаче.\n\n3. В переводном чеке индоссамент на плательщика имеет силу расписки за получение платежа.\n\nИндоссамент, совершенный плательщиком, является недействительным.\n\nЛицо, владеющее переводным чеком, полученным по индоссаменту, считается его законным владельцем, если оно основывает свое право на непрерывном ряде индоссаментов.","article_title":"Статья 880. Передача прав по чеку","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"633f1ed580f42f4ad0e1d75e82147acdc457b51c514e177d9afd641769f42268"},{"code_id":"GK_RF_2","article_number":"881","version_date":"1994-11-30","article_text":"1. Платеж по чеку может быть гарантирован полностью или частично посредством аваля.\n\nГарантия платежа по чеку (аваль) может даваться любым лицом, за исключением плательщика.\n\n2. Аваль проставляется на лицевой стороне чека или на дополнительном листе путем надписи \"считать за аваль\" и указания, кем и за кого он дан. Если не указано, за кого он дан, то считается, что аваль дан за чекодателя.\n\nАваль подписывается авалистом с указанием места его жительства и даты совершения надписи, а если авалистом является юридическое лицо, места его нахождения и даты совершения надписи.\n\n3. Авалист отвечает так же, как и тот, за кого он дал аваль.\n\nЕго обязательство действительно даже в том случае, если обязательство, которое он гарантировал, окажется недействительным по какому бы то ни было основанию, иному, чем несоблюдение формы.\n\n4. Авалист, оплативший чек, приобретает права, вытекающие из чека, против того, за кого он дал гарантию, и против тех, кто обязан перед последним.","article_title":"Статья 881. Гарантия платежа","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0eacb7fed881272a945e3dc03361b82cc79909a082cd5ba09a7522ff38a7f890"},{"code_id":"GK_RF_2","article_number":"882","version_date":"1994-11-30","article_text":"1. Представление чека в банк, обслуживающий чекодержателя, на инкассо для получения платежа считается предъявлением чека к платежу.\n\nОплата чека производится в порядке, установленном статьей 875 настоящего Кодекса.\n\n2. Зачисление средств по инкассированному чеку на счет чекодержателя производится после получения платежа от плательщика, если иное не предусмотрено договором между чекодержателем и банком.","article_title":"Статья 882. Инкассирование чека","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f3fc1980d7e8e12b3c34a7ba028e4e94e31c9086cfe16fce7d3d78abee672150"},{"code_id":"GK_RF_2","article_number":"883","version_date":"1994-11-30","article_text":"1. Отказ от оплаты чека должен быть удостоверен одним из следующих способов:\n\n1) совершением нотариусом протеста либо составлением равнозначного акта в порядке, установленном законом;\n\n2) отметкой плательщика на чеке об отказе в его оплате с указанием даты представления чека к оплате;\n\n3) отметкой инкассирующего банка с указанием даты о том, что чек своевременно выставлен и не оплачен.\n\n2. Протест или равнозначный акт должен быть совершен до истечения срока для предъявления чека.\n\nЕсли предъявление чека имело место в последний день срока, протест или равнозначный акт может быть совершен в следующий рабочий день.","article_title":"Статья 883. Удостоверение отказа от оплаты чека","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"08ab91c90d0984628dedad8e07acefb60814115ae1eb399d0551e648013ae262"},{"code_id":"GK_RF_2","article_number":"884","version_date":"1994-11-30","article_text":"Чекодержатель обязан известить своего индоссанта и чекодателя о неплатеже в течение двух рабочих дней, следующих за днем совершения протеста или равнозначного акта.\n\nКаждый индоссант должен в течение двух рабочих дней, следующих за днем получения им извещения, довести до сведения своего индоссанта полученное им извещение. В тот же срок направляется извещение тому, кто дал аваль за это лицо.\n\nНе пославший извещение в указанный срок не теряет своих прав. Он возмещает убытки, которые могут произойти вследствие неизвещения о неоплате чека. Размер возмещаемых убытков не может превышать сумму чека.","article_title":"Статья 884. Извещение о неоплате чека","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9bac909829fd40b7c2e2569bd86019d362d6882ad7237890e22285212abeb725"},{"code_id":"GK_RF_2","article_number":"885","version_date":"1994-11-30","article_text":"1. В случае отказа плательщика от оплаты чека чекодержатель вправе по своему выбору предъявить иск к одному, нескольким или ко всем обязанным по чеку лицам (чекодателю, авалистам, индоссантам), которые несут перед ним солидарную ответственность.\n\n2. Чекодержатель вправе потребовать от указанных лиц оплаты суммы чека, своих издержек на получение оплаты, а также процентов в соответствии с пунктом 1 статьи 395 настоящего Кодекса.\n\nТакое же право принадлежит обязанному по чеку лицу после того, как оно оплатило чек.\n\n3. Иск чекодержателя к лицам, указанным в пункте 1 настоящей статьи, может быть предъявлен в течение шести месяцев со дня окончания срока предъявления чека к платежу. Регрессные требования по искам обязанных лиц друг к другу погашаются с истечением шести месяцев со дня, когда соответствующее обязанное лицо удовлетворило требование, или со дня предъявления ему иска.","article_title":"Статья 885. Последствия неоплаты чека","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7b8c58d4d1741155a9b6d7e68791fe07b2f1ad80f8d88de0b9785f60d258151e"},{"code_id":"GK_RF_2","article_number":"886","version_date":"1994-11-30","article_text":"1. По договору хранения одна сторона (хранитель) обязуется хранить вещь, переданную ей другой стороной (поклажедателем), и возвратить эту вещь в сохранности.\n\n2. В договоре хранения, в котором хранителем является коммерческая организация либо некоммерческая организация, осуществляющая хранение в качестве одной из целей своей профессиональной деятельности (профессиональный хранитель), может быть предусмотрена обязанность хранителя принять на хранение вещь от поклажедателя в предусмотренный договором срок.","article_title":"Статья 886. Договор хранения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fcb0116eba25fe01a74653c11010c8913245df9f99056bee1c1e7c83e959e755"},{"code_id":"GK_RF_2","article_number":"887","version_date":"1994-11-30","article_text":"Договор хранения, предусматривающий обязанность хранителя принять вещь на хранение, должен быть заключен в письменной форме независимо от состава участников этого договора и стоимости вещи, передаваемой на хранение.\n\nПередача вещи на хранение при чрезвычайных обстоятельствах (пожаре, стихийном бедствии, внезапной болезни, угрозе нападения и т.п.) может быть доказываема свидетельскими показаниями.\n\nсохранной расписки, квитанции, свидетельства или иного документа, подписанного хранителем;\n\nномерного жетона (номера), иного знака, удостоверяющего прием вещей на хранение, если такая форма подтверждения приема вещей на хранение предусмотрена законом или иным правовым актом либо обычна для данного вида хранения.","article_title":"Статья 887. Форма договора хранения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e8d659e1836dad1c6d074b0cb26392f017a3797d184524246ec719bfa69b84c2"},{"code_id":"GK_RF_2","article_number":"888","version_date":"1994-11-30","article_text":"1. Хранитель, взявший на себя по договору хранения обязанность принять вещь на хранение (пункт 2 статьи 886), не вправе требовать передачи ему этой вещи на хранение.\n\nОднако поклажедатель, не передавший вещь на хранение в предусмотренный договором срок, несет ответственность перед хранителем за убытки, причиненные в связи с несостоявшимся хранением, если иное не предусмотрено законом или договором хранения. Поклажедатель освобождается от этой ответственности, если заявит хранителю об отказе от его услуг в разумный срок.\n\n2. Если иное не предусмотрено договором хранения, хранитель освобождается от обязанности принять вещь на хранение в случае, когда в обусловленный договором срок вещь не будет ему передана.","article_title":"Статья 888. Исполнение обязанности принять вещь на хранение","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9c7c2e9ac13dd215d3a495ab1b4b742930157420a9b3b5c15f088b819a8d585f"},{"code_id":"GK_RF_2","article_number":"889","version_date":"1994-11-30","article_text":"1. Хранитель обязан хранить вещь в течение обусловленного договором хранения срока.\n\n2. Если срок хранения договором не предусмотрен и не может быть определен исходя из его условий, хранитель обязан хранить вещь до востребования ее поклажедателем.\n\n3. Если срок хранения определен моментом востребования вещи поклажедателем, хранитель вправе по истечении обычного при данных обстоятельствах срока хранения вещи потребовать от поклажедателя взять обратно вещь, предоставив ему для этого разумный срок. Неисполнение поклажедателем этой обязанности влечет последствия, предусмотренные статьей 899 настоящего Кодекса.","article_title":"Статья 889. Срок хранения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7435e3f59e38cde8f6975e1b9f0243b87bf17f2a1b0cfb57fec2f8b85cc82e77"},{"code_id":"GK_RF_2","article_number":"890","version_date":"1994-11-30","article_text":"В случаях, прямо предусмотренных договором хранения, принятые на хранение вещи одного поклажедателя могут смешиваться с вещами того же рода и качества других поклажедателей (хранение с обезличением). Поклажедателю возвращается равное или обусловленное сторонами количество вещей того же рода и качества.","article_title":"Статья 890. Хранение вещей с обезличением","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1ac15fa297c71ecfa08910b43b0c411508fb0c88b6dd6318becc0765f6bfbbae"},{"code_id":"GK_RF_2","article_number":"891","version_date":"1994-11-30","article_text":"1. Хранитель обязан принять все предусмотренные договором хранения меры для того, чтобы обеспечить сохранность переданной на хранение вещи.\n\nПри отсутствии в договоре условий о таких мерах или неполноте этих условий хранитель должен принять для сохранения вещи также меры, соответствующие обычаям делового оборота и существу обязательства, в том числе свойствам переданной на хранение вещи, если только необходимость принятия этих мер не исключена договором.\n\n2. Хранитель во всяком случае должен принять для сохранения переданной ему вещи меры, обязательность которых предусмотрена законом, иными правовыми актами или в установленном ими порядке (противопожарные, санитарные, охранные и т.п.).\n\n3. Если хранение осуществляется безвозмездно, хранитель обязан заботиться о принятой на хранение вещи не менее, чем о своих вещах.","article_title":"Статья 891. Обязанность хранителя обеспечить сохранность вещи","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a11a9ece480da498a67b09381c6ac979cae6d2460eb29341c8da137f61f1af60"},{"code_id":"GK_RF_2","article_number":"892","version_date":"1994-11-30","article_text":"Хранитель не вправе без согласия поклажедателя пользоваться переданной на хранение вещью, а равно предоставлять возможность пользования ею третьим лицам, за исключением случая, когда пользование хранимой вещью необходимо для обеспечения ее сохранности и не противоречит договору хранения.","article_title":"Статья 892. Пользование вещью, переданной на хранение","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c271d7dd446ae315ea414c1bd91c143a957b016fd9341249832dba0ab07bc9e8"}]$law7d0037$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
commit;
